from abc import ABC, abstractmethod

class SortAlgorithm(ABC):
    def __init__(self, data):
        self.data = data

    # Template method: defines the skeleton of the sorting algorithm
    def sort(self):
        n = len(self.data)
        for i in range(n - 1):
            for j in range(n - 1 - i):
                if self.compare(j, j + 1) > 0:
                    self.swap(j, j + 1)

    @abstractmethod
    def compare(self, i, j):
        pass

    @abstractmethod
    def swap(self, i, j):
        pass


class BubbleSort(SortAlgorithm):
    # BubbleSort uses the template method defined in the base class
    def sort(self):
        super().sort()

    def compare(self, i, j):
        a, b = self.data[i], self.data[j]
        if a < b:
            return -1
        elif a > b:
            return 1
        else:
            return 0

    def swap(self, i, j):
        self.data[i], self.data[j] = self.data[j], self.data[i]


class SelectionSort(SortAlgorithm):
    def sort(self):
        n = len(self.data)
        for i in range(n):
            min_idx = i
            for j in range(i + 1, n):
                if self.compare(j, min_idx) < 0:
                    min_idx = j
            if min_idx != i:
                self.swap(i, min_idx)

    def compare(self, i, j):
        a, b = self.data[i], self.data[j]
        if a < b:
            return -1
        elif a > b:
            return 1
        else:
            return 0

    def swap(self, i, j):
        self.data[i], self.data[j] = self.data[j], self.data[i]


def test_sort_algorithms():
    # Test with integers using BubbleSort (template method)
    arr_int = [64, 34, 25, 12, 22, 11, 90]
    bubble = BubbleSort(arr_int.copy())
    bubble.sort()
    print("BubbleSort integers:", bubble.data)

    # Test with integers using SelectionSort
    arr_int2 = [64, 34, 25, 12, 22, 11, 90]
    select = SelectionSort(arr_int2.copy())
    select.sort()
    print("SelectionSort integers:", select.data)

    # Test with strings using BubbleSort
    arr_str = ["pear", "apple", "orange", "banana"]
    bubble_s = BubbleSort(arr_str.copy())
    bubble_s.sort()
    print("BubbleSort strings:", bubble_s.data)

    # Test with strings using SelectionSort
    arr_str2 = ["pear", "apple", "orange", "banana"]
    select_s = SelectionSort(arr_str2.copy())
    select_s.sort()
    print("SelectionSort strings:", select_s.data)


if __name__ == "__main__":
    test_sort_algorithms()
